export const LESSON_YAML: Record<string, string> = {
  "01-hello": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 01 · Hello world — the smallest COMPLETE Nika workflow.\n#\n# Four questions, four answers, and nothing else: what does it run on, what\n# may it touch, what does it do, what does it hand back. A file that skips\n# one of the four still executes — it just stops being a contract.\n#\n# Demonstrates ·\n#   - the envelope · `nika: v1` (the contract version) + `workflow.id`\n#   - `model:` · one local model · no API key, nothing leaves the machine\n#   - `permits: {}` · the DECLARED zero · this workflow may touch nothing\n#   - one task · the `infer:` verb, bounded by `max_tokens:`\n#   - `outputs:` · the value a caller gets back\n#\n# Needs · ollama with the model pulled · `ollama pull qwen3.5:4b`.\n#   No ollama? The dry twin runs anywhere, zero setup ·\n#   `nika run examples/01-hello.nika.yaml --model mock/echo`\n#\n# Run · nika run examples/01-hello.nika.yaml\n\nnika: hello\n\nmodel: ollama/qwen3.5:4b   # local · zero key · swap for any provider in the catalog\n\n# The declared zero. `permits:` is default-deny once present, so an empty\n# block is a statement, not a formality: this workflow opens no file, reaches\n# no host, runs no program. Leaving the block out says something different —\n# that no boundary was declared — and both forms refuse an effecting tool at\n# run, with different verdicts: an absent block reports NIKA-AUTH-006 (no\n# boundary to judge against), `permits: {}` reports NIKA-SEC-004 (outside the\n# boundary you drew). Declaring the zero is what puts the checker's PERMITS\n# and TRIFECTA judges on duty — under-declaring quietly stands them down.\npermits: {}\n\ntasks:\n  greet:\n    infer:\n      prompt: \"Say hello in French, in one short sentence.\"\n      # The ceiling. On a priced model this is what turns the cost report from\n      # UNBOUNDED into a hard worst-case number.\n      #\n      # 2048 for two words looks absurd until you measure it. `max_tokens` caps\n      # think + answer, and qwen3.5 is a reasoning model that deliberates before\n      # it speaks — on this exact prompt: 64 → \"\", 256 → \"\", 512 → \"\", 1024 →\n      # \"Bonjour.\", 2048 → \"Bonjour !\". Under the threshold the run is GREEN and\n      # the output is EMPTY, because the budget ran out mid-thought. Size the\n      # cap for the thinking, or pick a non-thinking model (llama3.2:3b) when\n      # you want a tight one.\n      max_tokens: 2048\n\n# The return value. It does NOT appear on the live run — that surface shows\n# progress. `--output json` is the export contract: the typed `outputs:` as\n# ONE JSON object on stdout, which is how a caller reads a workflow's result\n# (`exec: nika run sub.nika.yaml --output json` + `capture: stdout`).\n#\n#   nika run examples/01-hello.nika.yaml --output json\n#   → {\"greeting\":\"Bonjour !\"}\noutputs:\n  greeting: ${{ tasks.greet.output }}\n",
  "02-parallel-fanout": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 02 · Parallel fan-out + merge — the core DAG pattern.\n#\n# You never write \"run these in parallel\". You write what each task NEEDS,\n# and the shape of the graph falls out: three tasks that need nothing from\n# each other are three tasks the engine may run at once. Concurrency is a\n# consequence of the dependencies, not an instruction.\n#\n# Demonstrates ·\n#   - implicit parallelism · no deps between three tasks → one wave, run together\n#   - `const:` · a fixed value baked into the file, never caller-supplied\n#   - `with:` value edges · what a task binds is what it waits for\n#   - `${{ tasks.<id>.output }}` · reading an upstream result\n#\n# DAG shape ·   angle ─┐\n#               cost  ─┼─→ synthesize\n#               risk  ─┘\n#\n# Run · nika run examples/02-parallel-fanout.nika.yaml\n\nnika: parallel-fanout\n\n# The dry twin, on purpose: this file teaches SHAPE, and the twin makes the\n# shape visible — it echoes each prompt back, so `synthesize`'s output shows\n# the three upstream answers arriving inside it. Swap in any real model\n# (`--model ollama/qwen3.5:4b`) and only the prose changes, never the graph.\nmodel: mock/echo\n\npermits: {}   # pure compute · no file, no host, no program (see 01)\n\nconst:\n  topic: \"adopting Rust for a backend rewrite\"\n\ntasks:\n  # No task below names another, so the engine puts all three in wave 1 and\n  # runs them concurrently. `nika check` prints the waves it derived — read\n  # that plan before you reach for a knob to make something parallel.\n  angle:\n    infer:\n      prompt: \"Give the strategic angle on · ${{ const.topic }}\"\n      max_tokens: 512\n\n  cost:\n    infer:\n      prompt: \"Give the cost angle on · ${{ const.topic }}\"\n      max_tokens: 512\n\n  risk:\n    infer:\n      prompt: \"Give the risk angle on · ${{ const.topic }}\"\n      max_tokens: 512\n\n  # The merge. `with:` does two jobs at once: it aliases the upstream outputs\n  # to short local names, and — because a binding IS a dependency — it is what\n  # puts this task in wave 2. Bind three tasks, wait for three tasks.\n  synthesize:\n    with:\n      a: ${{ tasks.angle.output }}\n      c: ${{ tasks.cost.output }}\n      r: ${{ tasks.risk.output }}\n    infer:\n      prompt: |\n        Synthesize one recommendation from three analyses.\n        Strategy · ${{ with.a }}\n        Cost · ${{ with.c }}\n        Risk · ${{ with.r }}\n      max_tokens: 1024\n\n# The return value · read it with `--output json` (see 01).\noutputs:\n  recommendation: ${{ tasks.synthesize.output }}\n",
  "03-exec-pipeline": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 03 · exec pipeline — shell, a conditional gate, cleanup on every outcome.\n#\n# Run the tests; ship only if they pass; release the build lock either way.\n# The interesting part is what \"pass\" means here: a red suite is not a broken\n# workflow, it is a NUMBER the next task reads. The pipeline succeeds at\n# finding out the tests failed.\n#\n# Demonstrates ·\n#   - the `exec:` verb · its two doors, `shell:` (a line) and `command:` (an argv array)\n#   - `capture: structured` · `.output` is { stdout, stderr, exit_code }\n#   - `timeout:` · a Go-duration string, quoted · hard kill, retries included\n#   - `run.clock` · naming the clock that deadline rides\n#   - `with:` + `when:` · a DATA edge · the exit code crosses, the CEL gate reads it\n#   - `after:` · a STATE edge · admit a task on the producer's outcome\n#   - `after: {…: unwind}` · cleanup as a TASK · runs on every outcome of a\n#     STARTED producer (success · fail · timeout · cancel) · a producer that\n#     never started unwinds nothing\n#\n# Runs green anywhere the suite is not passing — no Cargo.toml, or no cargo at\n# all, is a non-zero exit: the gate closes, the deploy is skipped, the notice\n# fires. Exactly the story a red suite tells. Run it inside a repo whose tests\n# DO pass and the gate opens onto `./deploy.sh`, which is yours to supply.\n#\n# Run · nika run examples/03-exec-pipeline.nika.yaml\n\nnika: exec-pipeline\n\nrun:\n  # `timeout:` below has to be measured against something. Left undeclared it\n  # rides the ambient system clock — the honest default, never a refusal — but\n  # the choice is then invisible in the file. Say it out loud. (`virtual` runs\n  # deadlines on a simulated clock instead, for tests that must not wait.)\n  clock: system\n\npermits:\n  # `true`, not a program list, and the checker will tell you why if you try:\n  # « a shell-string command cannot be verified against a `permits.exec`\n  # program allowlist (a pipeline can launch any program) — use the array\n  # form ». `test` below wants a shell line, so the allowlist is off the table\n  # for this file. A workflow whose steps are all `command:` arrays can — and\n  # should — write the tight form instead: `exec: [\"cargo\", \"rm\"]`.\n  exec: true\n\ntasks:\n  test:\n    timeout: \"5m\"\n    exec:\n      # Door 1 · a shell line. Pipes, globs and `&&` work; a program allowlist\n      # cannot bound it.\n      shell: \"cargo test --workspace --lib\"\n      cwd: \".\"             # the directory you ran `nika` from, not the file's\n      capture: structured  # → { stdout, stderr, exit_code }\n\n  release_lock:\n    # ALWAYS runs · best-effort · an error here is logged, never propagated.\n    # A lock outlives the thing that took it unless something like this\n    # releases it on the failure and timeout paths too. Cleanup is a TASK on\n    # an `unwind` edge — one grammar, so it is greppable and testable.\n    after: { test: unwind }\n    exec:\n      command: [\"rm\", \"-f\", \"./.build.lock\"]\n\n  deploy:\n    with:\n      # `capture: structured` is what makes this possible: a non-zero exit\n      # becomes DATA instead of a failure. The task above is ✔ and its\n      # `.status` is `success` — it ran the command and found out. The red\n      # suite lives in `exit_code`, and nowhere else. Gate on the number, and\n      # never on the task status, or you will ship a broken build.\n      exit_code: ${{ tasks.test.output.exit_code }}\n    when: ${{ with.exit_code == 0 }}   # red → skipped · green → ship\n    exec:\n      # Door 2 · an argv array. No shell, no word-splitting, and every program\n      # in it is checkable against `permits.exec`.\n      command: [\"./deploy.sh\"]\n      cwd: \".\"\n\n  no_ship_notice:\n    # The third edge kind. `with:` carries DATA and `when:` reads it; `after:`\n    # carries STATE — it admits this task on the producer's outcome and nothing\n    # else. The vocabulary is success · failure · skipped · terminal (terminal =\n    # any settled state, cancelled included).\n    #\n    # `deploy` is skipped whenever the gate above closes, so this is \"the ship\n    # did not go out\" — a fact you cannot express with a value edge, because a\n    # skipped task has no value to bind.\n    after:\n      deploy: skipped\n    exec:\n      command: [\"echo\", \"deploy skipped · the suite was red\"]\n\n# Both halves of the story, so a reader can see them disagree · read with\n# `--output json`. In an empty directory with no cargo on PATH, measured:\n#   {\"suite_exit_code\": 127, \"task_status\": \"success\"}\n# The number is whatever the command returned — 127 is the shell saying\n# `cargo` was not found, and even that is just a number the gate reads.\noutputs:\n  suite_exit_code: ${{ tasks.test.output.exit_code }}\n  task_status: ${{ tasks.test.status }}\n",
  "04-schema-retry": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 04 · Structured output + retry — an LLM call you can index into.\n#\n# Without `schema:` a model hands back a paragraph and every downstream task\n# is string-surgery. With it, `.output` is an object: you write\n# `.output.entities` and the engine has already made that true, or failed\n# loudly trying. This is the line between a prompt and an API.\n#\n# Demonstrates ·\n#   - `infer.schema:` · a JSON Schema the model MUST satisfy\n#   - `additionalProperties: false` · the shape is closed, not merely suggested\n#   - `retry:` · transient-error policy · attempts + backoff + jitter\n#   - typed `inputs:` with a `default:` · runs with no flags, `--var` overrides\n#   - indexing a structured result · `${{ tasks.extract.output.entities }}`\n#   - the long `outputs:` form · `value:` + `type:` + `description:`\n#\n# Run · nika run examples/04-schema-retry.nika.yaml\n#   with your own text · nika run examples/04-schema-retry.nika.yaml \\\n#     --var text=\"Marie Curie worked in Paris for the Sorbonne\"\n\nnika: schema-retry\n\nmodel: mock/echo   # the dry twin · swap `--model ollama/qwen3.5:4b` for a real extraction\n\npermits: {}        # pure compute · no file, no host, no program (see 01)\n\ninputs:\n  text:\n    type: string\n    # A `default:` is what makes this file runnable with zero flags. `required`\n    # stays true: it says the task cannot proceed without a value, not that the\n    # caller must type one. `--var text=…` overrides the default.\n    default: \"Ada Lovelace met Charles Babbage in London\"\n    required: true\n    description: \"Free text to extract named entities from — people, places, organizations, returned as schema-guaranteed structured JSON\"\n\ntasks:\n  extract:\n    infer:\n      prompt: \"Extract named entities from · ${{ inputs.text }}\"\n      max_tokens: 1024\n      schema:\n        type: object\n        # Closed on purpose. Without this a provider may add keys of its own\n        # and two providers give you two shapes for one workflow; the checker\n        # flags the open form as a strictness hint for exactly that reason.\n        additionalProperties: false\n        required: [entities]\n        properties:\n          entities:\n            type: array\n            items:\n              type: object\n              additionalProperties: false\n              required: [name, type]\n              properties:\n                name: { type: string }\n                type: { type: string, enum: [person, place, organization] }\n    retry:\n      # For TRANSIENT failures — a provider 503, a dropped connection. A\n      # response that misses the schema is a different animal: a validation\n      # error (NIKA-INFER-002 · transient: false), which retry: never fires\n      # on — any re-ask is the engine's own, internal (02-verbs.md §infer).\n      max_attempts: 3\n      backoff_strategy: exponential   # 1s · 2s · 4s …\n      jitter: true                    # anti-thundering-herd (the default)\n\n  report:\n    with:\n      # `.output` is an object here because `schema:` was set, so this indexes\n      # straight into it. Drop the schema and this same expression is reaching\n      # into a string.\n      entities: ${{ tasks.extract.output.entities }}\n    infer:\n      prompt: \"Write one sentence summarizing these entities · ${{ with.entities }}\"\n      max_tokens: 512\n\n# The long form · a typed return contract. `value:` carries the binding, and\n# `type:`/`description:` describe it for a caller reading the workflow's\n# signature rather than its body. Measured with the twin:\n#   {\"entities\":[{\"name\":\"mock\",\"type\":\"person\"}],\"summary\":\"mock(echo) · …\"}\noutputs:\n  entities:\n    value: ${{ tasks.extract.output.entities }}\n    description: \"The extracted named entities\"\n  summary:\n    value: ${{ tasks.report.output }}\n    type: string\n    description: \"One sentence covering them\"\n",
  "05-fetch-chain": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 05 · Fetch → bind → summarize, with a fallback that keeps the shape.\n#\n# The first file that reaches outside the process. Two things follow from\n# that: the workflow has to say which host it may reach, and it has to have\n# an answer for the day that host is down. Both are declarations, not code.\n#\n# Demonstrates ·\n#   - `invoke:` · calling a TOOL · fetching is `nika:fetch`, not a verb\n#   - `permits.net.http` · the hosts this workflow may reach, named exactly\n#   - `extract:` · named jq bindings → `${{ tasks.<id>.<name> }}`\n#   - `on_error: recover:` · a literal fallback that substitutes the raw\n#     output BEFORE extraction, so the SAME bindings work on both paths\n#   - chaining a tool result into an `infer:` prompt\n#\n# Runs green offline: the placeholder host resolves nowhere, the recovery\n# value takes over, the summary still lands. That is the point — the\n# rehearsal exercises the failure path, which is the one you cannot test\n# by waiting for it.\n#\n# Run · nika run examples/05-fetch-chain.nika.yaml\n\nnika: fetch-chain\n\nmodel: mock/echo   # the dry twin · the lesson here is the tool call, not the prose\n\nconst:\n  api_url: \"https://api.example.com/v1/articles/latest\"\n\npermits:\n  tools: [\"nika:fetch\"]\n  net:\n    # The one host `const.api_url` names. A `const` is the one authority a run\n    # cannot move, so the host is knowable while checking and the bound is\n    # written here rather than deferred.\n    #\n    # Worth knowing before you build on this: when a URL arrives from a secret\n    # or an input instead, `check` cannot see the host and stays green — the\n    # boundary is then judged mid-run, after tokens are spent. Exact names\n    # only; this list never takes globs.\n    http: [\"api.example.com\"]\n\ntasks:\n  fetch_article:\n    invoke:\n      tool: nika:fetch\n      args:\n        url: \"${{ const.api_url }}\"\n        mode: jq    # extract structured fields · not a markdown dump\n        jq: \".\"\n    extract:\n      # Named jq bindings over the tool's result. Downstream reads\n      # `${{ tasks.fetch_article.title }}` — not `.output.data.title`.\n      title: \".data.title\"\n      body: \".data.body\"\n    on_error:\n      # The literal fallback. It substitutes the RAW result before the\n      # bindings above run, which is the whole reason it has to mirror the\n      # live response shape — `{ data: { title, body } }`. Get the shape\n      # wrong and the recovery succeeds while the bindings come back empty.\n      # (A recover can also point at another task · 05-errors §recovery.)\n      recover:\n        data:\n          title: \"Cached fallback article\"\n          body: \"The archived copy — good enough for a summary when the live API is down.\"\n\n  summarize:\n    with:\n      title: ${{ tasks.fetch_article.title }}\n      body: ${{ tasks.fetch_article.body }}\n    infer:\n      prompt: |\n        Summarize this article in 3 bullets.\n        Title · ${{ with.title }}\n        Body · ${{ with.body }}\n      max_tokens: 512\n\n# `title` is here so a reader can see WHICH path ran: offline it reads\n# \"Cached fallback article\". Read with `--output json`.\noutputs:\n  title: ${{ tasks.fetch_article.title }}\n  summary: ${{ tasks.summarize.output }}\n",
  "06-code-review": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 06 · Code-review agent — a loop you do not write.\n#\n# The first five files are graphs: you decide the steps. Here you decide the\n# BOUNDS — which tools, how many turns, how many tokens — and the model\n# decides the steps inside them. That is the whole trade, and the reason the\n# grants below matter more than the prompt does.\n#\n# Demonstrates ·\n#   - the `agent:` verb · model + tools, looping until done or out of budget\n#   - `tools:` · a default-deny whitelist · the agent gets ONLY these\n#   - `max_turns:` + `max_tokens_total:` · the two budget caps\n#   - `nika:done` · the completion sentinel that lets the loop end cleanly\n#   - the workflow boundary applies INSIDE the loop · granting the agent\n#     `nika:read` is not enough, the files need `permits.fs.read` too\n#\n# Runs fully offline on a local tool-calling model, against a fixture\n# committed next to this file. Measured: 2 turns, ~1.6k tokens of the 8000\n# budget — it reads once, then reports. Wall clock is whatever your machine\n# and a resident-or-cold model make it (30s and 5m both observed here).\n#\n# Needs · ollama with the model pulled · `ollama pull qwen3.5:4b`.\n#\n# Run · nika run examples/06-code-review.nika.yaml   (from the repo root ·\n#   paths resolve against your working directory, not the file's location)\n\nnika: code-review\n\nmodel: ollama/qwen3.5:4b   # local tool-calling model · zero key · the diff never leaves the machine\n\nconst:\n  target: \"./examples/fixtures/review-me.rs\"\n\npermits:\n  tools: [\"nika:done\", \"nika:read\"]\n  fs:\n    # The agent may call `nika:read`, and it may read THIS file. Those are two\n    # different permissions and both are required — a tool grant with no\n    # `fs.read` behind it fails mid-loop with\n    # « NIKA-SEC-004 · agent tool `nika:read` refused by the security boundary »,\n    # after the model has already spent a turn deciding to read.\n    #\n    # To review your own file, change this line AND `const.target` together.\n    # The permit does not follow the path around; that is what makes it a wall.\n    # (A bound cannot interpolate — `${{ const.target }}` here is NIKA-AUTH-007.)\n    read: [\"./examples/fixtures/review-me.rs\"]\n\ntasks:\n  review:\n    agent:\n      # Default-deny: this list IS the agent's universe. Anything not named\n      # here does not exist as far as the loop is concerned — there is no\n      # ambient toolbox to opt out of.\n      tools:\n        # `nika:done` first is deliberate: the whitelist order means nothing\n        # to a real model, but the OFFLINE rehearsal (`--model mock/echo`)\n        # invokes the first granted tool — done-first lets the mock close the\n        # loop cleanly at turn one, where a synthesized `nika:read` path\n        # would be refused by the fs boundary and kill the rehearsal.\n        - \"nika:done\"   # say \"finished\" and end the loop cleanly\n        - \"nika:read\"   # open the file under review\n      # Two independent stops, because they fail differently: a model that\n      # ping-pongs forever hits `max_turns`, a model that reads something huge\n      # hits `max_tokens_total`. The loop also just ends when the model\n      # returns no tool call.\n      max_turns: 8\n      max_tokens_total: 8000\n      system: |\n        You are a senior Rust reviewer.\n        Read the file you are given with nika:read, then reply with your\n        findings as a short markdown list — one line per finding, each\n        starting with blocker/high/med/low. Then call nika:done.\n      prompt: \"Review ${{ const.target }} and report bugs and style issues.\"\n\n# The agent's final message. It is free text — an agent answer is prose unless\n# you constrain it, and constraining it is a separate job (see 04 for the\n# schema machinery).\noutputs:\n  findings: ${{ tasks.review.output }}\n",
  "07-for-each-locales": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 07 · for_each fan-out — one task, many items.\n#\n# 02 fanned out by writing three tasks. That works until the list is decided\n# at run time, or has fifty entries. `for_each:` is the same fan-out with the\n# collection as data: one task definition, one iteration per element, and a\n# `.output` that is the array of results in input order.\n#\n# Demonstrates ·\n#   - `for_each:` · run a task once per element of a collection\n#   - `${{ item }}` + `${{ index }}` · loop-scoped locals, not a namespace\n#   - `for_each.max_parallel:` · a ceiling on concurrent iterations\n#   - `for_each.fail_fast: false` · finish the batch even when one element fails\n#   - fan-in · the whole array lands in one downstream binding\n#\n# Run · nika run examples/07-for-each-locales.nika.yaml\n\nnika: for-each-locales\n\nmodel: mock/echo   # the dry twin · this file teaches the loop, not the translations\n\npermits: {}        # pure compute · no file, no host, no program (see 01)\n\nconst:\n  source: \"Welcome to the launch.\"\n  locales: [\"fr\", \"es\", \"de\", \"ja\", \"pt\"]\n\ntasks:\n  translate:\n    for_each:\n      items: ${{ const.locales }}      # five elements → five iterations\n      max_parallel: 3                  # at most 3 in flight · the rest queue\n      # Default is fail_fast: true — the first failure cancels the siblings.\n      # A batch job usually wants the opposite: four good translations beat\n      # zero, and you would rather learn which one broke.\n      fail_fast: false\n    on_error:\n      # Without this, a failed element fails the task even under\n      # fail_fast: false. `recover: null` keeps the array whole and puts a\n      # null at that index — a fan-in over a batch that CAN fail must\n      # expect those nulls (this rehearsal's mock path never produces one).\n      recover: null\n    with:\n      locale: ${{ item }}   # the current element\n      n: ${{ index }}       # its 0-based position\n    infer:\n      prompt: \"Translate to locale '${{ with.locale }}' (#${{ with.n }}) · ${{ const.source }}\"\n      max_tokens: 256\n\n  collect:\n    with:\n      # One binding, five results. `tasks.translate.output` is the ARRAY, in\n      # the order of `const.locales` — not the order they finished.\n      translations: ${{ tasks.translate.output }}\n    infer:\n      prompt: \"Combine these translations into a localization table · ${{ with.translations }}\"\n      max_tokens: 1024\n\n# Both the array and the table, so the ordering guarantee is visible · read\n# with `--output json`.\noutputs:\n  translations: ${{ tasks.translate.output }}\n  table: ${{ tasks.collect.output }}\n",
  "08-config-values": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 08 · The deployment's knobs — one authority, two roles.\n#\n# THREE authorities can put a value in a workflow: `inputs:` (declared once,\n# supplied by the caller OR by its own `default:`) · `const:` (the author,\n# fixed in the file) · `secrets:` (a governed store reference, masked, and it\n# lives with the jobs · CONVENTIONS §3).\n#\n# A deployment knob — a region label, a verbosity switch — is an `inputs:`\n# entry with `required: false` and a `default:`. It used to have a block of\n# its own, `config:`, and that block is dead: it had zero usage in real work,\n# its `default:` was its only possible source, and under the taint lattice\n# `config.p` and `inputs.p` produced the SAME refusal by the same path. Two\n# authorities the checker cannot tell apart are one authority.\n#\n# Demonstrates ·\n#   - a knob · typed, `required: false`, `default:`-carrying\n#   - declared-only resolution · an undeclared `${{ inputs.x }}` is\n#     `NIKA-VAR-001` — the engine NEVER falls back to the OS environment\n#     (spec/01-envelope.md §inputs)\n#   - `when:` on a knob · a quiet run and a verbose run, one file\n#   - who supplies what · `--var` reaches every `inputs:` entry, knob or not\n#\n# Run · nika run examples/08-config-values.nika.yaml\n#   The verbose twin · flip `verbose.default` to true and run again.\n\nnika: config-values\n\npermits:\n  tools: [\"nika:jq\", \"nika:log\"]\n\ninputs:\n  team:\n    type: string\n    default: \"atelier\"\n    required: true\n    description: \"Whose report this is — the CALLER's value · --var team=…\"\n  # The deployment's knobs — `required: false` + a `default:` is what makes\n  # this file runnable everywhere with nobody supplying anything. Never a\n  # credential here: an input's value appears in logs and traces\n  # (spec/01-envelope.md §secrets) — a value that must stay masked belongs\n  # to `secrets:`.\n  region:\n    required: false\n    type: string\n    default: \"eu\"\n    description: \"Which region label the report carries\"\n  verbose:\n    required: false\n    type: bool\n    default: false\n    description: \"Emit the debug dump task when true\"\n\nconst:\n  # The author's number — fixed in the file, never supplied by anyone.\n  window_days: 7\n\ntasks:\n  report:\n    invoke:\n      tool: \"nika:jq\"\n      args:\n        input:\n          team: \"${{ inputs.team }}\"\n          region: \"${{ inputs.region }}\"\n          window_days: \"${{ const.window_days }}\"\n        expression: '. + {title: \"\\(.team) · \\(.region) · last \\(.window_days) days\"}'\n\n  debug_dump:\n    with:\n      report: ${{ tasks.report.output }}\n    # A knob routes WORK — it never stands in for a human decision\n    # (spec/10-authority.md · \"a `when:` on an input flag is not a gate\").\n    # False by default: this task settles `skipped`, and nothing downstream\n    # reads it, so the quiet run stays quiet. The shape rule (cel-subset)\n    # wants an explicit relation — `== true`, never the bare flag.\n    when: ${{ inputs.verbose == true }}\n    invoke:\n      tool: \"nika:log\"\n      args:\n        level: debug\n        message: \"full report object\"\n        data: \"${{ with.report }}\"\n\noutputs:\n  report:\n    value: ${{ tasks.report.output }}\n    description: \"The shaped report · title carries team + region + window\"\n",
  "09-returns-typed-door": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 09 · Returns — the typed door on a task's output.\n#\n# 04 typed a model's answer with `infer.schema:`. `returns:` is the door\n# that types ANY task's output — a field of the task, sibling of the verb,\n# one grammar for all four verbs. Declare the shape once and every deep\n# reference downstream is checked against it, statically where the engine\n# can, at settle where it cannot.\n#\n# Demonstrates ·\n#   - a type expression written INLINE · self-contained, no name to look up\n#   - `returns:` on `infer:` · compiled into the structured-output contract\n#     (so `returns:` + `schema:` on one task is refused · `NIKA-TYPE-003` ·\n#     one-obvious-way/011: `returns:` is the one way)\n#   - `returns:` on `invoke:` · the run asserts the decoded value fits\n#   - a `returns:`-typed object is CLOSED · referencing a member it does\n#     not declare is `NIKA-VAR-003`, caught before anything runs\n#   - typed `outputs:` · the workflow's own signature, readable by a caller\n#\n# Run · nika run examples/09-returns-typed-door.nika.yaml\n\nnika: returns-typed-door\n\nmodel: mock/echo   # the dry twin · swap `--model ollama/qwen3.5:4b` for real extraction\n\npermits:\n  tools: [\"nika:jq\"]\n\ninputs:\n  text:\n    type: string\n    default: \"Ada Lovelace met Charles Babbage in London\"\n    required: true\n    description: \"Free text to extract named entities from\"\n\ntasks:\n  extract:\n    infer:\n      prompt: \"Extract named entities from · ${{ inputs.text }}\"\n      max_tokens: 512\n    # The type expression IS the contract: for `infer:` it lowers to the\n    # same structured-output floor 04 built with `schema:` — the model's\n    # answer is validated against it, or the task fails loudly. The grammar\n    # is closed and small: 10 primitives · array · map · object · union ·\n    # optional (field position only — a nullable ROOT is\n    # `{ union: [T, \"null\"] }`, spec/09-types.md) · enum · bounded numbers.\n    returns:\n      object:\n        entities:\n          array:\n            object:\n              name: string\n              kind: string\n\n  stats:\n    with:\n      # This deep reference is legal BECAUSE `returns:` declared the member.\n      # A `returns:`-typed object is closed: `.output.entitles` (typo'd)\n      # would be NIKA-VAR-003 at check, not a null at midnight.\n      entities: ${{ tasks.extract.output.entities }}\n    invoke:\n      tool: \"nika:jq\"\n      args:\n        input: \"${{ with.entities }}\"\n        expression: \"{count: length}\"\n    # On `invoke:` the door is an assertion on the decoded value at settle:\n    # jq's output must fit, or the task fails with the shape mismatch named.\n    returns: { object: { count: integer } }\n\n# A workflow whose outputs are typed is a workflow another file can CALL —\n# the signature a caller reads without opening the body. 10 does exactly\n# that.\noutputs:\n  count:\n    value: ${{ tasks.stats.output.count }}\n    type: integer\n    description: \"How many entities were extracted\"\n  entities:\n    value: ${{ tasks.extract.output.entities }}\n    description: \"The extracted entities · name + kind\"\n",
  "10-compose-child": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 10 · Compose (the child) — a callable unit.\n#\n# The second half of lesson 10: a workflow written to be CALLED. Its\n# `inputs:` are the parameters a parent may pass, its typed `outputs:` are\n# the whole surface a parent can read — nothing else crosses the wall.\n# Read `10-compose-pipeline.nika.yaml` first; it invokes this file.\n#\n# Demonstrates ·\n#   - the callable contract · `inputs:` in, typed `outputs:` out\n#   - a child declares its OWN `permits:` · an absent block is the declared\n#     zero (NEP-0003) — a parent's grants NEVER descend implicitly, so this\n#     file says `permits: {}` itself, and would still have to name every\n#     effect it dared to make\n#\n# Run · nika run examples/10-compose-child.nika.yaml --var topic=\"the DAG\"\n#   (standalone run · the parent passes `topic` through `args:` instead)\n\nnika: compose-child\n\nmodel: mock/echo   # the dry twin · the parent's run stays offline too\n\n# The child's OWN boundary. Composition confines every child effect to\n# `parent ∩ child-declared` — an empty child boundary means there is\n# nothing to confine, and a child that fetched or wrote with this block\n# empty would be `NIKA-COMP-002` at the parent's check.\npermits: {}\n\ninputs:\n  topic:\n    # The `default:` is what keeps the standalone run flag-free (04's\n    # rule); a calling parent overrides it through `args:` every time.\n    type: string\n    default: \"the DAG\"\n    required: true\n    description: \"What to brief · supplied by the caller through `args:`\"\n\ntasks:\n  brief:\n    infer:\n      prompt: \"Write a two-sentence brief on · ${{ inputs.topic }}\"\n      max_tokens: 512\n\noutputs:\n  summary:\n    value: ${{ tasks.brief.output }}\n    type: string\n    description: \"The brief · the ONE thing a caller can read from this file\"\n",
  "10-compose-pipeline": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 10 · Compose — one workflow calls another.\n#\n# Anything non-trivial is built from parts, and this is the door: a task\n# whose `invoke:` names a `workflow:` instead of a `tool:`. The target is\n# a STATIC path (never `${{ }}` · `NIKA-COMP-001`), resolved relative to\n# THIS file; `args:` feed the child's declared `inputs:`; the task's\n# `.output` is the closed object of the child's `outputs:` — the wall\n# between the two files is the child's signature, nothing more.\n#\n# Demonstrates ·\n#   - `invoke: { workflow:, args: }` · the composition door\n#   - `returns:` on the call · names the child-outputs contract the parent\n#     relies on (child outputs that do not fit are `NIKA-COMP-004`)\n#   - `${{ tasks.call.output.<field> }}` · reading a child output by name\n#   - effect confinement · a child effect must sit inside\n#     `parent ∩ child-declared` (`NIKA-COMP-002`) · the child declares its\n#     own boundary, grants never descend (NEP-0003)\n#   - the call graph is checked acyclic (`NIKA-COMP-003` · a self-call is a\n#     one-node cycle) and depth-capped at run (`NIKA-SEC-003` · 8 deep)\n#\n# Run · nika run examples/10-compose-pipeline.nika.yaml\n#   The child is an ingredient · ./10-compose-child.nika.yaml must sit beside\n#   this file. Taken alone, check refuses before anything runs — NIKA-COMP-001\n#   names the missing file (measured · a bare copy dies on exactly that).\n\nnika: compose-pipeline\n\nmodel: mock/echo   # the dry twin — and the child carries its own seat\n\npermits:\n  # The parent's boundary covers the parent's OWN effect (one jq). The\n  # child is pure compute behind `permits: {}`, so there is nothing of its\n  # to hold here — a child that read files would need `fs.read` in BOTH\n  # boundaries before its effect survives the intersection.\n  tools: [\"nika:jq\"]\n\ninputs:\n  topic:\n    type: string\n    default: \"why a workflow calls a workflow\"\n    required: true\n    description: \"Passed through to the child's `topic` input\"\n\ntasks:\n  call:\n    invoke:\n      # Relative to THIS file, static, checked before anything runs: the\n      # COMPOSITION rung proves `direct child calls are static, typed and\n      # contained · closure acyclic` — and stays silent on files that call\n      # no one, which is why the path never showed it before this lesson.\n      workflow: \"./10-compose-child.nika.yaml\"\n      args:\n        # Each key must be a DECLARED child input (`NIKA-COMP-004` names an\n        # unknown one) · values may interpolate; the target may not.\n        topic: \"${{ inputs.topic }}\"\n    # The typed door again (09), now naming what the parent relies on from\n    # the child's signature: `summary` must exist there, as a string.\n    returns: { object: { summary: string } }\n\n  wrap:\n    with:\n      summary: ${{ tasks.call.output.summary }}\n    invoke:\n      tool: \"nika:jq\"\n      args:\n        input:\n          topic: \"${{ inputs.topic }}\"\n          summary: \"${{ with.summary }}\"\n        expression: \". + {chars: (.summary | length)}\"\n\noutputs:\n  brief:\n    value: ${{ tasks.wrap.output }}\n    description: \"topic + the child's summary + its length · one object\"\n",
  "11-declassify-the-door": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 11 · The lift — the one door through the taint.\n#\n# A permit-relevant argument fed by an UNTRUSTED value (`inputs.*` ·\n# `config.*` · anything fetched) is the parameterisation taint. When the\n# check can resolve the value and it ESCAPES the bound, it refuses with\n# `NIKA-AUTH-008` — and the reflex that refusal provokes (widen the\n# boundary until the message stops) is the wrong door. The right one is\n# authored: a `lift:` entry naming the **taint** law on the task, with a\n# reviewable `because:`\n# (spec/10-authority.md · \"The only door is the authored one\").\n#\n# Demonstrates · every claim below was run against this exact file\n#   - the wall · flip this file's `default:` to \"../outside/secrets.csv\"\n#     and the check refuses ✖ NIKA-AUTH-008; the door below turns that\n#     SAME variant check-green — the static question is deferred, not\n#     answered\n#   - never a bypass · that deferred variant still dies `NIKA-SEC-004` at\n#     run, and `--var path=README.md` on THIS file dies the same way — the\n#     boundary confines every value, door or no door\n#     (spec/10-authority.md · \"It is never a permit bypass\")\n#   - `lift:` · task-level · `law:` a closed enum (`taint` here) · `from:`\n#     a dotted binding, required by `taint` and forbidden elsewhere ·\n#     `because:` non-empty, the review record\n#   - what the door yields on an ADMITTED value · the vouching lands in\n#     the signed trace — one `lift` frame per entry, holding the\n#     `because:`\n#   - a wall with no door at all · a permit BOUND can never interpolate\n#     (`NIKA-AUTH-007` · a bound is a literal you can read)\n#\n# Run · nika run examples/11-declassify-the-door.nika.yaml\n#   another vendor file · --var path=examples/fixtures/orders.csv\n\nnika: declassify-the-door\n\npermits:\n  tools: [\"nika:jq\", \"nika:read\"]\n  fs:\n    # The bound is the DOMAIN the operator grants: any fixture csv, one\n    # path segment, nothing nested. `*` never crosses `/` — a caller aiming\n    # at `fixtures/deep/x.csv` or `../secrets.csv` is refused by the\n    # boundary itself, before the taint question even comes up.\n    read: [\"examples/fixtures/*.csv\"]\n\ninputs:\n  path:\n    type: string\n    default: \"examples/fixtures/inventory-q3.csv\"\n    required: true\n    description: \"WHICH vendor csv to load · must sit inside the fs.read bound\"\n\ntasks:\n  load:\n    invoke:\n      tool: \"nika:read\"\n      args:\n        path: \"${{ inputs.path }}\"\n    # The door. `law:` names WHICH law this entry lifts; `from:` names the\n    # exact tainted binding; `because:` is the sentence a reviewer holds\n    # you to. What it buys, measured: a resolvable ESCAPING value stops\n    # refusing at check (the question is handed to the run), and every run\n    # writes one `lift` frame into the signed trace carrying this exact\n    # sentence. What it does not buy, measured: the boundary — an\n    # out-of-bound path dies `NIKA-SEC-004` at run with the door in place.\n    lift:\n      - law: taint\n        from: inputs.path\n        because: \"the caller picks WHICH fixture csv, never an arbitrary path — the one-segment *.csv bound confines every value this input can take, and the run refuses anything outside it\"\n\n  shape:\n    with:\n      raw: ${{ tasks.load.output }}\n    invoke:\n      tool: \"nika:jq\"\n      args:\n        input: \"${{ with.raw }}\"\n        expression: '{rows: (split(\"\\n\") | map(select(. != \"\")) | length - 1)}'\n\noutputs:\n  summary:\n    value: ${{ tasks.shape.output }}\n    description: \"How many data rows the vendor file carries (header excluded)\"\n",
  "12-failure-routing": "# SPDX-License-Identifier: Apache-2.0\n# yaml-language-server: $schema=https://nika.sh/spec/v1/workflow.schema.json\n#\n# 12 · Failure routing — the paths a run takes when it breaks.\n#\n# 03 drew control edges with `after:` and `success`/`skipped`. This lesson\n# adds the arm nobody rehearses: a task that runs ONLY when its producer\n# fails, and a cleanup hook in its full form. The file is a drill — flip\n# one flag and watch the failure path fire, offline, deterministically.\n#\n# Demonstrates ·\n#   - `after: { deploy: failure }` · the pass-set is strictly {failure} —\n#     it admits neither `success` nor `cancelled` (the whatever-happens\n#     word is `terminal`)\n#   - a skipped arm is a VALUE · on the green run the failure arm settles\n#     `cancelled`, which is dead-path elimination, not an error\n#   - real WORK on the failure path · the sanctioned use — `retry:` covers\n#     transient errors, `on_error: recover:` covers a fallback value, a\n#     failure-edge task is for work (one-obvious-way/003 · /004)\n#   - cleanup as a TASK on an `unwind` edge · `when:` + `timeout:` are the\n#     ordinary task fields, not a second grammar · cleanup errors are logged,\n#     never propagated · a producer that never STARTED unwinds nothing\n#\n# Run · nika run examples/12-failure-routing.nika.yaml\n#   the drill · nika run examples/12-failure-routing.nika.yaml --var drill=true\n#     — the deploy fails ON PURPOSE, the run exits red, and out/incident.md\n#     is the artifact that proves the failure arm ran.\n\nnika: failure-routing\n\npermits:\n  exec: false\n  tools: [\"nika:assert\", \"nika:log\", \"nika:write\"]\n  fs:\n    write: [\"out/incident.md\", \"out/release-note.md\"]\n\ninputs:\n  drill:\n    type: bool\n    default: false\n    required: true\n    description: \"true = rehearse the failure path · the deploy fails on purpose\"\n\ntasks:\n  deploy:\n    # The assert stands in for the risky step so the drill stays offline\n    # and deterministic — in a real file this is the release command. When\n    # `--var drill=true` the condition is false and the task settles\n    # `failure`, which is exactly what the two arms below route on.\n    invoke:\n      tool: \"nika:assert\"\n      args:\n        condition: \"${{ inputs.drill == false }}\"\n        message: \"drill requested · the deploy step fails on purpose\"\n  release_lock:\n    # Cleanup is a TASK on an `unwind` edge — `when:` and `timeout:` are the\n    # ordinary task fields, not a second grammar. It runs once `deploy` has\n    # STARTED, on every settle — and its errors are logged, never propagated:\n    # a cleanup can never turn a green run red. An unwind task may read the\n    # producer it unwinds (settled by definition) and nothing else.\n    after: { deploy: unwind }\n    when: ${{ tasks.deploy.status != \"success\" }}\n    timeout: \"10s\"\n    invoke:\n      tool: \"nika:log\"\n      args:\n        level: warn\n        message: \"deploy settled ${{ tasks.deploy.status }} · lock released\"\n\n  publish:\n    after: { deploy: success }\n    invoke:\n      tool: \"nika:write\"\n      args:\n        path: \"out/release-note.md\"\n        content: \"release went out · deploy green\\n\"\n        create_dirs: true\n        overwrite: true\n\n  rollback:\n    # Strictly the failure arm. On the green run this task settles\n    # `cancelled` — its producer never entered the pass-set, so the path is\n    # eliminated as a value, not reported as an error; the render says so\n    # in one line: `⊘ rollback  gate: an edge did not admit`. On the drill\n    # run it does real work: the incident record IS the reason this is a\n    # task and not a `recover:`.\n    after: { deploy: failure }\n    invoke:\n      tool: \"nika:write\"\n      args:\n        path: \"out/incident.md\"\n        content: \"deploy failed · rollback engaged · see the trace for the settle order\\n\"\n        create_dirs: true\n        overwrite: true\n\noutputs:\n  # The settle the two arms routed on. Measured on the green run:\n  # `--output json` hands back {\"deploy_status\":\"success\"}.\n  deploy_status: ${{ tasks.deploy.status }}\n",
}
